import os
import sys
import random

from TBClasses.shared.utilities import get_repo_root

repo_root = get_repo_root()
sys.path.insert(0, repo_root)

import cocotb
import pytest
from cocotb_test.simulator import run  # noqa: F401

from TBClasses.shared.utilities import get_paths
from projects.components.bridge.dv.tbclasses.bridge1x2_rw_apb5_mon_tb import Bridge1x2RwApb5MonTB
from monitor_stress_common import run_comprehensive, run_monitor_sim

CFG_PREFIXES = ['cpu_0_rd', 'cpu_0_wr', 'sram_0_rd', 'sram_0_wr', 'periph5_1_rd', 'periph5_1_wr']
BLOCK_READY_PATH = "u_cpu_adapter.u_timing_wrapper_rd"
REACHABLE_SLAVES = [0]
HAS_COMPL = True
IS_REGBLOCK = False


@cocotb.test(timeout_time=600, timeout_unit="ms")
async def cocotb_test_bridge_1x2_rw_apb5_mon_monitor(dut):
    tb = Bridge1x2RwApb5MonTB(dut)
    await tb.setup_clocks_and_reset()
    await run_comprehensive(
        dut, tb,
        cfg_prefixes=CFG_PREFIXES,
        block_ready_path=BLOCK_READY_PATH,
        reachable_slaves=REACHABLE_SLAVES,
        has_compl=HAS_COMPL,
        is_regblock=IS_REGBLOCK,
    )


def generate_bridge_levels():
    """REG_LEVEL selects the grid: the test_level cells this wrapper expands to.

    GATE 1 (gate), FUNC 2 (gate, func), FULL 3 (gate, func, full) -- different
    counts, so the three make targets run different matrices. The depth each
    cell runs at is read by the TB from TEST_LEVEL (bridge_levels.PROFILE)."""
    reg_level = os.environ.get('REG_LEVEL', 'FUNC').upper()
    if reg_level == 'GATE':
        return ['gate']
    if reg_level == 'FUNC':
        return ['gate', 'func']
    return ['gate', 'func', 'full']


bridge_levels = generate_bridge_levels()


@pytest.mark.parametrize("test_level", bridge_levels)
def test_bridge_1x2_rw_apb5_mon_monitor(request, test_level):
    module, repo_root_, tests_dir, log_dir, _ = get_paths({
        'rtl_amba': '../../../../rtl/amba',
    })
    run_monitor_sim(
        module=module, repo_root=repo_root_, tests_dir=tests_dir, log_dir=log_dir,
        dut_name="bridge_1x2_rw_apb5_mon",
        testcase="cocotb_test_bridge_1x2_rw_apb5_mon_monitor",
        filelist='projects/components/bridge/rtl/filelists/bridge_1x2_rw_apb5_mon.f',
        test_level=test_level,
        extra_env={
            'SEED': os.environ.get('SEED', str(random.randint(0, 100000))),
            'TEST_LEVEL': test_level,
        },
    )
